  File skipDir=new File(System.getProperty("java.io.tmpdir"),"skip-lifecycle-host");skipDir.mkdirs();new File(skipDir,"med_reminder.db").delete();Store skips=new Store(new Context(skipDir));long sid=skips.saveMed(0,"Skip fixture","1 mg","08:00,20:00","",true);Store.Med sm=skips.med(sid);long skipNow=at("2026-11-04T19:00:00"),skipAt=at("2026-11-04T20:00:00"),tomorrowMorning=at("2026-11-05T08:00:00"),tomorrowEvening=at("2026-11-05T20:00:00");String skipKey=Core.occurrence(sid,sm.revision,skipAt);if(!Alarms.mayDeliver(skips,sid,sm.revision,skipKey,skipAt))throw new AssertionError("valid pending notification rejected");long skipId=skips.skipOccurrence(sid,sm.revision,skipKey,skipAt,"Asia/Shanghai");if(skipId<=0)throw new AssertionError("skip failed");eq(skips.skipOccurrence(sid,sm.revision,skipKey,skipAt,"Asia/Shanghai"),skipId);if(skips.forOccurrence(skipKey)!=null||!skips.isSkipped(skipKey)||!skips.logs().isEmpty()||Alarms.mayDeliver(skips,sid,sm.revision,skipKey,skipAt))throw new AssertionError("skip became a dose record or late notice remained eligible");if(Alarms.pendingByMed(skips,new java.util.HashSet<>(java.util.Arrays.asList(skipKey))).containsKey(Long.toString(sid)))throw new AssertionError("skipped slot retained after user decision");if(!DoseStats.summarize(skips.logs(),0,Long.MAX_VALUE).groups.isEmpty())throw new AssertionError("skip contributed to actual-dose stats");eq(Alarms.nextForMed(skips,sm,skipNow,"Asia/Shanghai"),tomorrowMorning);skips=new Store(new Context(skipDir));sm=skips.med(sid);if(!skips.isSkipped(skipKey))throw new AssertionError("skip did not persist on reopen");if(skips.confirm(sid,sm.revision,skipKey,skipAt,skipNow,"0.5 mg")!=-1||!skips.logs().isEmpty())throw new AssertionError("late confirmation callback recorded skipped occurrence");if(!skips.undoSkip(sid,sm.revision,skipKey))throw new AssertionError("undo failed");eq(Alarms.nextForMed(skips,sm,skipNow,"Asia/Shanghai"),skipAt);long custom=skips.confirm(sid,sm.revision,skipKey,skipAt,skipNow,"0.5 mg");if(custom<=0)throw new AssertionError("restored custom confirmation failed");eq(skips.log(custom).plannedAt,skipAt);eq(skips.log(custom).actualAt,skipNow);if(!"0.5 mg".equals(skips.log(custom).dose))throw new AssertionError("custom dose not stored");if(!"0.5".equals(DoseStats.summarize(skips.logs(),0,Long.MAX_VALUE).find(sid,"mg").totalText()))throw new AssertionError("custom actual dose total incorrect");if(skips.skipOccurrence(sid,sm.revision,skipKey,skipAt,"Asia/Shanghai")!=-1)throw new AssertionError("skip replaced an actual record");if(Alarms.mayDeliver(skips,sid,sm.revision,skipKey,skipAt))throw new AssertionError("notification eligible after actual confirmation");eq(Alarms.nextForMed(skips,sm,skipNow,"Asia/Shanghai"),tomorrowMorning);eq(sm.anchor,0);if(skips.undoSkip(sid,sm.revision,skipKey))throw new AssertionError("undo removed actual record");
  String nextKey=Core.occurrence(sid,sm.revision,tomorrowMorning);long nextSkip=skips.skipOccurrence(sid,sm.revision,nextKey,tomorrowMorning,"Asia/Shanghai");if(nextSkip<=0)throw new AssertionError("next-day skip failed");eq(Alarms.nextForMed(skips,sm,skipNow,"Asia/Shanghai"),tomorrowEvening);Store.Med changed=skips.med(sid);skips.saveMetadata(sid,changed.name,changed.dose,"changed",true);if(skips.skipOccurrence(sid,changed.revision,nextKey,tomorrowMorning,"Asia/Shanghai")!=-1)throw new AssertionError("skip accepted stale occurrence revision");eq(skips.med(sid).revision,changed.revision+1);eq(skips.log(custom).plannedAt,skipAt);
  File stableSkipDir=new File(System.getProperty("java.io.tmpdir"),"skip-stable-revision-host");stableSkipDir.mkdirs();new File(stableSkipDir,"med_reminder.db").delete();Store stableSkips=new Store(new Context(stableSkipDir));long stableMedId=stableSkips.saveMed(0,"Stable skip fixture","1 mg","20:00","",true);Store.Med rev1=stableSkips.med(stableMedId);long stablePlanned=at("2026-11-04T20:00:00"),stableNow=at("2026-11-04T19:00:00"),nextPlanned=at("2026-11-05T20:00:00");String rev1Key=Core.occurrence(stableMedId,rev1.revision,stablePlanned);long stableSkipId=stableSkips.skipOccurrence(stableMedId,rev1.revision,rev1Key,stablePlanned,"Asia/Shanghai");if(stableSkipId<=0)throw new AssertionError("initial stable skip failed");stableSkips.saveMetadata(stableMedId,rev1.name,rev1.dose,"same schedule, new revision",true);Store.Med rev2=stableSkips.med(stableMedId);String rev2Key=Core.occurrence(stableMedId,rev2.revision,stablePlanned);if(rev2.revision==rev1.revision||!stableSkips.isSkipped(rev2Key))throw new AssertionError("same med+planned skip did not carry across revision");eq(stableSkips.skipOccurrence(stableMedId,rev2.revision,rev2Key,stablePlanned,"Asia/Shanghai"),stableSkipId);eq(Alarms.nextUnconfirmed(stableSkips,rev2,"20:00",stableNow,"Asia/Shanghai"),nextPlanned);TodayPlan carried=TodayPlan.build(stableSkips.meds(true),stableSkips.logs(),stableSkips.skips(),stableNow,"Asia/Shanghai");if(carried.skipped.size()!=1||carried.skipped.get(0).plannedAt!=stablePlanned)throw new AssertionError("Today did not retain stable skip after revision");String stableNextKey=Core.occurrence(stableMedId,rev2.revision,nextPlanned);if(stableSkips.skipOccurrence(stableMedId,rev2.revision,stableNextKey,nextPlanned,"Asia/Shanghai")<=0)throw new AssertionError("second occurrence skip failed");if(stableSkips.undoSkip(stableMedId,rev1.revision,rev1Key,"Asia/Shanghai"))throw new AssertionError("stale revision undo accepted");if(!stableSkips.undoSkip(stableMedId,rev2.revision,rev2Key,"Asia/Shanghai"))throw new AssertionError("current revision could not undo carried skip");if(stableSkips.isSkipped(stableMedId,stablePlanned)||!stableSkips.isSkipped(stableMedId,nextPlanned)||stableSkips.skips().size()!=1)throw new AssertionError("undo removed wrong stable skip decision");eq(Alarms.nextUnconfirmed(stableSkips,rev2,"20:00",stableNow,"Asia/Shanghai"),stablePlanned);if(stableSkips.skipOccurrence(stableMedId,rev1.revision,rev1Key,stablePlanned,"Asia/Shanghai")!=-1)throw new AssertionError("stale revision skip accepted");
  File upgradeDir=new File(System.getProperty("java.io.tmpdir"),"schema-v3-to-v4-host");upgradeDir.mkdirs();File upgradeDb=new File(upgradeDir,"med_reminder.db");upgradeDb.delete();try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+upgradeDb);Statement q=db.createStatement()){q.execute("CREATE TABLE meds(_id INTEGER PRIMARY KEY AUTOINCREMENT,revision INTEGER NOT NULL,name TEXT NOT NULL,dose TEXT NOT NULL,times TEXT NOT NULL,notes TEXT NOT NULL,active INTEGER NOT NULL,schedule_mode TEXT NOT NULL,anchor_at INTEGER NOT NULL,frequency_days INTEGER NOT NULL,frequency_count INTEGER NOT NULL)");q.execute("CREATE TABLE logs(_id INTEGER PRIMARY KEY AUTOINCREMENT,med_id INTEGER NOT NULL,planned_at INTEGER NOT NULL,actual_at INTEGER NOT NULL,med_name TEXT NOT NULL,dose TEXT NOT NULL,notes TEXT NOT NULL,occurrence TEXT NOT NULL UNIQUE,manual INTEGER NOT NULL)");q.execute("CREATE UNIQUE INDEX logs_planned_occurrence ON logs(med_id,planned_at) WHERE manual=0");q.execute("INSERT INTO meds VALUES(1,7,'Existing fixture','2 mg','08:00','kept',1,'FIXED',0,0,0)");q.execute("INSERT INTO logs VALUES(1,1,1793865600000,1793865500000,'Existing fixture','2 mg','preserve','1:7:1793865600000',0)");q.execute("PRAGMA user_version=3");}Store upgraded=new Store(new Context(upgradeDir));if(upgraded.med(1)==null||upgraded.log(1)==null||!upgraded.skips().isEmpty())throw new AssertionError("v3 upgrade failed to preserve existing data/add empty skips");eq(upgraded.log(1).actualAt,1793865500000L);
  File fdir=new File(System.getProperty("java.io.tmpdir"),"alarm-frequency-host");fdir.mkdirs();new File(fdir,"med_reminder.db").delete();Store fs=new Store(new Context(fdir));long fid=fs.saveFrequencyMed(0,"Fixture frequency","1 tablet",at("2026-11-04T08:00:00"),1,3,"",true);Store.Med fm=fs.med(fid);long fa=fm.anchor, fnow=fa-3600000L;eq(Alarms.nextForMed(fs,fm,fnow,"Asia/Shanghai"),fa);fs.confirm(fid,fm.revision,Core.occurrence(fid,fm.revision,fa),fa,fnow);eq(Alarms.nextForMed(fs,fm,fnow,"Asia/Shanghai"),Core.frequencyAt(fa,1,3,1));eq(fs.med(fid).anchor,fa);
  long denseAnchor=1793750400000L,denseId=fs.saveFrequencyMed(0,"Fixture dense","1 tablet",denseAnchor,1,1000,"",true);Store.Med dense=fs.med(denseId);for(int i=0;i<1002;i++){long planned=Core.frequencyAt(denseAnchor,1,1000,i);long saved=fs.confirm(denseId,dense.revision,Core.occurrence(denseId,dense.revision,planned),planned,denseAnchor);if(saved<=0)throw new AssertionError("dense frequency fixture confirmation failed at "+i);}eq(Alarms.nextFrequencyUnconfirmed(fs,dense,denseAnchor-1,"UTC"),Core.frequencyAt(denseAnchor,1,1000,1002));
  System.out.println("AlarmPendingHostTest OK (legacy and anchored frequency alarms, early confirmation, revision and reopen)");
